&quot;Yo quiero un Lamborghini&quot;) ## [1] 24 22.4.2 Combinar cadenas con str_c Nota aquí que une la primera oración con la segunda oración str_c(&quot;Es una oración con muchas letras y palabras&quot;, &quot;Mi pelicula favorita es Cinema Paraiso&quot;) ## [1] &quot;Es una oración con muchas letras y palabrasMi pelicula favorita es Cinema Paraiso&quot; Usa el argumento sep = “xxx” para controlar cómo separar las oraciones str_c(&quot;Es una oración con muchas letras y palabras&quot;, &quot;Mi pelicula favorita es Cinema Paraiso&quot;, sep = &quot;, &quot;) ## [1] &quot;Es una oración con muchas letras y palabras, Mi pelicula favorita es Cinema Paraiso&quot; str_replace_na() x &lt;- c(&quot;Mi pelicula favorita es Cinema Paraiso&quot;, NA) x ## [1] &quot;Mi pelicula favorita es Cinema Paraiso&quot; ## [2] NA str_c(&quot;|-&quot;, x, &quot;-|&quot;) ## [1] &quot;|-Mi pelicula favorita es Cinema Paraiso-|&quot; ## [2] NA 22.5 Dividir cadenas basado en la posición de los caracteres en la cadena str_sub() x= c( &quot;Piña&quot;, &quot;Manzana&quot;, &quot;Toronja&quot;) str_sub(x, 1,1) ## [1] &quot;P&quot; &quot;M&quot; &quot;T&quot; 22.5.1 Seleccionar los caracteres al último de las palabras x= c( &quot;Piña&quot;, &quot;Manzana&quot;, &quot;Toronja&quot;, &quot;Hello&quot;) str_sub(x, -2,-1) ## [1] &quot;ña&quot; &quot;na&quot; &quot;ja&quot; &quot;lo&quot; 22.6 También se puede usar str_sub() para modificar una cadena x &lt;- &quot;BBCDEF&quot; str_sub(x, 1, 1) &lt;- &quot;A&quot;; x ## [1] &quot;ABCDEF&quot; x &lt;- &quot;BBCDEF&quot; str_sub(x, -1, -1) &lt;- &quot;K&quot;; x ## [1] &quot;BBCDEK&quot; x &lt;- &quot;BBCDEF&quot; str_sub(x, -2, -2) &lt;- &quot;GHIJ&quot;; x ## [1] &quot;BBCDGHIJF&quot; x &lt;- &quot;BBCDEF&quot; str_sub(x, -3, -3) &lt;- &quot;BC&quot;; x ## [1] &quot;BBCBCEF&quot; x &lt;- &quot;BBCDEF&quot; str_sub(x, 2, -2) &lt;- &quot;&quot;; x ## [1] &quot;BF&quot; 22.6.1 Cambiar a todo minúscula x= c( &quot;Piña&quot;, &quot;Manzana&quot;, &quot;Toronja&quot;, &quot;HAPPY&quot;) str_to_lower(x) ## [1] &quot;piña&quot; &quot;manzana&quot; &quot;toronja&quot; &quot;happy&quot; 22.6.2 Cambiar a mayúscula x= c( &quot;Piña&quot;, &quot;Manzana&quot;, &quot;Toronja&quot;) str_to_upper(x) ## [1] &quot;PIÑA&quot; &quot;MANZANA&quot; &quot;TORONJA&quot; 22.7 Locales ¿Qué es un locale? str_to_lower() str_to_upper() str_order() # que hace esta función? str_sort() # que hace esta función? x ## [1] &quot;Piña&quot; &quot;Manzana&quot; &quot;Toronja&quot; str_order(x) # regresa el orden de las palabras ## [1] 2 1 3 str_sort(x) # reorganiza las palabras en orden alfabético ## [1] &quot;Manzana&quot; &quot;Piña&quot; &quot;Toronja&quot; Ejercicios del libro R4DS. Hacer los ejercicios en la sección 14.2.5 del libro en español 22.8 Buscar patrones Las expresiones regulares surgieron en los años 1950 del trabajo del matemático Stephen Kleene sobre lenguajes formales, y hoy son el estándar para describir patrones de texto en casi todos los lenguajes de programación. 22.9 Coincidencia básica Para visualizar patrones de letras str_view() str_view( , .x.) library(stringr) x &lt;- c(&quot;manzana&quot;, &quot;banana&quot;, &quot;pera&quot;, &quot;extraer&quot;) str_view(x, &quot;er&quot;) ## [3] │ p&lt;er&gt;a ## [4] │ extra&lt;er&gt; Ejemplo de cómo uno puede utilizar esas funciones str_detect() x= c( &quot;Piña&quot;, &quot;Manzana&quot;, &quot;Toronja&quot;, &quot;Jugo&quot;, &quot;Monique&quot;, &quot;Raymond&quot;, &quot;mami&quot;) str_detect(x, &quot;a&quot;) # detectar la a ## [1] TRUE TRUE TRUE FALSE FALSE TRUE TRUE str_detect(x, &quot;i&quot;) # detectar la i ## [1] TRUE FALSE FALSE FALSE TRUE FALSE TRUE str_detect(x, &quot;ñ&quot;) ## [1] TRUE FALSE FALSE FALSE FALSE FALSE FALSE 22.9.1 Detectar las palabras que comienzan con una letra específica con “^”. Nota el uso de mayúsculas y minúsculas y sumamos cuantas palabras cumplen con la condición. # ¿Cuántas palabras comunes empiezan con m o M? # str_detect(x, &quot;^M&quot;) x ## [1] &quot;Piña&quot; &quot;Manzana&quot; &quot;Toronja&quot; &quot;Jugo&quot; &quot;Monique&quot; &quot;Raymond&quot; &quot;mami&quot; sum(str_detect(x, &quot;^m&quot;)) ## [1] 1 sum(str_detect(x, &quot;^M&quot;)) ## [1] 2 sum(str_detect(x, &quot;^[mM]&quot;)) # ambas mayusculas y minusculas ## [1] 3 22.9.2 Detectar las palabras que terminan con una letra específica con “$” # ¿Qué proporción de palabras comunes terminan con una vocal? library(datos) mean(str_detect(palabras, &quot;[aáeéiíoóuú]$&quot;)) ## [1] 0.561 # ¿Qué proporción de palabras comunes terminan con una vocal especifica? mean(str_detect(palabras, &quot;[ao]$&quot;)) ## [1] 0.428 mean(str_detect(x, &quot;[d]$&quot;)) # Raymond ## [1] 0.1428571 Dataset: palabras Comienza para mirar el archivo palabras Cuentas palabras tiene ese archivo? library(stringr) library(datos) palabras ## [1] &quot;a&quot; &quot;abril&quot; &quot;acción&quot; &quot;acciones&quot; ## [5] &quot;acerca&quot; &quot;actitud&quot; &quot;actividad&quot; &quot;actividades&quot; ## [9] &quot;acto&quot; &quot;actual&quot; &quot;acuerdo&quot; &quot;adelante&quot; ## [13] &quot;además&quot; &quot;administración&quot; &quot;afirmó&quot; &quot;agua&quot; ## [17] &quot;ahí&quot; &quot;ahora&quot; &quot;aire&quot; &quot;al&quot; ## [21] &quot;algo&quot; &quot;alguien&quot; &quot;algún&quot; &quot;alguna&quot; ## [25] &quot;algunas&quot; &quot;algunos&quot; &quot;allá&quot; &quot;allí&quot; ## [29] &quot;alrededor&quot; &quot;alta&quot; &quot;alto&quot; &quot;ambiente&quot; ## [33] &quot;ambos&quot; &quot;américa&quot; &quot;amigo&quot; &quot;amigos&quot; ## [37] &quot;amor&quot; &quot;análisis&quot; &quot;animales&quot; &quot;ante&quot; ## [41] &quot;anterior&quot; &quot;antes&quot; &quot;antonio&quot; &quot;año&quot; ## [45] &quot;años&quot; &quot;aparece&quot; &quot;apenas&quot; &quot;apoyo&quot; ## [49] &quot;aquel&quot; &quot;aquella&quot; &quot;aquellas&quot; &quot;aquellos&quot; ## [53] &quot;aquí&quot; &quot;área&quot; &quot;a